select
    coalesce((
        select sum(loss.loss_quantity)
        from inv_transfer_receipt_discrepancy_damage_loss_ledger loss
        where loss.receipt_allocation_id = #{receiptAllocationId}
    ), 0.0000)
    + coalesce((
        select sum(reservation.reserved_quantity)
        from inv_transfer_quarantine_reservation reservation
        where reservation.receipt_allocation_id =
            #{receiptAllocationId}
    ), 0.0000)

select stock_id, item_type, item_id, product_id, shop_dept_id,
       warehouse_id, current_quantity, locked_quantity,
       available_quantity, quarantine_quantity, cost_price,
       total_cost, version
from inv_stock
where shop_dept_id = #{fact.targetWarehouseId}
  and warehouse_id = #{fact.targetWarehouseId}
  and item_type = #{fact.itemType}
  and item_id = #{fact.itemId}
for update

mapper.update:
update inv_stock
set locked_quantity = #{reservation.stock.lockedAfter},
    quarantine_quantity =
        #{reservation.stock.quarantineAfter},
    version = #{reservation.stockVersionAfter},
    update_by = #{reservation.source.executorName},
    update_time = sysdate()
where stock_id = #{reservation.stockId}
  and shop_dept_id = #{reservation.fact.targetWarehouseId}
  and warehouse_id = #{reservation.fact.targetWarehouseId}
  and item_type = #{reservation.source.itemType}
  and item_id = #{reservation.source.itemId}
  and version = #{reservation.stockVersionBefore}
  and current_quantity = #{reservation.stock.currentBefore}
  and available_quantity = #{reservation.stock.availableBefore}
  and locked_quantity = #{reservation.stock.lockedBefore}
  and quarantine_quantity =
      #{reservation.stock.quarantineBefore}
  and cost_price = #{reservation.stockCostPrice}
  and total_cost = #{reservation.stockTotalCost}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{reservation.stock.currentAfter} = current_quantity
  and #{reservation.stock.availableAfter} = available_quantity
  and #{reservation.stock.lockedAfter} = locked_quantity
      + #{reservation.source.quantity}
  and #{reservation.stock.quarantineAfter} = quarantine_quantity
      - #{reservation.source.quantity}
  and #{reservation.stockVersionAfter} = version + 1
  and quarantine_quantity >= #{reservation.source.quantity}

update inv_stock_balance_detail
set locked_quantity = #{reservation.balance.lockedAfter},
    quarantine_quantity =
        #{reservation.balance.quarantineAfter},
    version = #{reservation.balanceVersionAfter},
    update_by = #{reservation.source.executorName},
    update_time = sysdate()
where balance_id = #{reservation.balanceId}
  and warehouse_id = #{reservation.fact.targetWarehouseId}
  and item_type = #{reservation.source.itemType}
  and item_id = #{reservation.source.itemId}
  and lot_id = #{reservation.fact.quarantineLotId}
  and location_id = #{reservation.fact.quarantineLocationId}
  and version = #{reservation.balanceVersionBefore}
  and current_quantity = #{reservation.balance.currentBefore}
  and available_quantity =
      #{reservation.balance.availableBefore}
  and available_quantity = 0
  and locked_quantity = #{reservation.balance.lockedBefore}
  and quarantine_quantity =
      #{reservation.balance.quarantineBefore}
  and cost_price = #{reservation.balanceCostPrice}
  and cost_price = #{reservation.source.sourceCostPrice}
  and total_cost = #{reservation.balanceTotalCost}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{reservation.balance.currentAfter} = current_quantity
  and #{reservation.balance.availableAfter} = available_quantity
  and #{reservation.balance.lockedAfter} = locked_quantity
      + #{reservation.source.quantity}
  and #{reservation.balance.quarantineAfter} = quarantine_quantity
      - #{reservation.source.quantity}
  and #{reservation.balanceVersionAfter} = version + 1
  and quarantine_quantity >= #{reservation.source.quantity}

update inv_inventory_serial
set serial_status = #{serial.statusAfter},
    update_by = #{reservation.source.executorName},
    update_time = sysdate(),
    remark = concat('adjudication return reservation action=',
            #{reservation.source.actionId})
where serial_id = #{serial.serialId}
  and serial_no = #{serial.serialNo}
  and item_type = #{reservation.source.itemType}
  and item_id = #{reservation.source.itemId}
  and warehouse_id = #{reservation.fact.targetWarehouseId}
  and balance_id = #{reservation.fact.quarantineBalanceId}
  and lot_id = #{reservation.fact.quarantineLotId}
  and location_id = #{reservation.fact.quarantineLocationId}
  and serial_status = #{serial.statusBefore}
  and #{serial.statusAfter} = 'quarantine_reserved'

mapper.insert:
insert into inv_transfer_quarantine_reservation_serial (
    quarantine_reservation_id, request_id,
    adjudication_action_id, receipt_serial_id, serial_id,
    serial_no_snapshot, warehouse_id, balance_id, lot_id,
    location_id, status_before, status_after, create_by,
    create_time
)
select #{reservationId}, #{reservation.source.requestId},
       #{reservation.source.actionId}, rs.receipt_serial_id,
       rs.serial_id, rs.serial_no_snapshot,
       #{reservation.fact.targetWarehouseId},
       #{reservation.fact.quarantineBalanceId},
       #{reservation.fact.quarantineLotId},
       #{reservation.fact.quarantineLocationId},
       #{serial.statusBefore}, #{serial.statusAfter},
       #{reservation.source.executorName},
       #{reservation.source.createdAt}
from inv_transfer_quarantine_reservation owner
inner join inv_transfer_shipment_receipt_serial rs
        on rs.receipt_serial_id = #{serial.receiptSerialId}
       and rs.serial_id = #{serial.serialId}
       and rs.serial_no_snapshot = #{serial.serialNo}
       and rs.receipt_id = #{reservation.fact.receiptId}
       and rs.receipt_allocation_id =
           #{reservation.fact.receiptAllocationId}
       and rs.shipment_id = #{reservation.fact.shipmentId}
       and rs.shipment_allocation_id =
           #{reservation.fact.shipmentAllocationId}
       and rs.disposition = 'damaged'
       and rs.status_after = 'quarantine'
inner join inv_inventory_serial current_serial
        on current_serial.serial_id = rs.serial_id
       and current_serial.serial_no = rs.serial_no_snapshot
       and current_serial.item_type =
           #{reservation.source.itemType}
       and current_serial.item_id = #{reservation.source.itemId}
       and current_serial.warehouse_id =
           #{reservation.fact.targetWarehouseId}
       and current_serial.balance_id =
           #{reservation.fact.quarantineBalanceId}
       and current_serial.lot_id =
           #{reservation.fact.quarantineLotId}
       and current_serial.location_id =
           #{reservation.fact.quarantineLocationId}
       and current_serial.serial_status = #{serial.statusAfter}
where owner.quarantine_reservation_id = #{reservationId}
  and owner.request_id = #{reservation.source.requestId}
  and owner.adjudication_action_id =
      #{reservation.source.actionId}
  and #{serial.statusBefore} = 'quarantine'
  and #{serial.statusAfter} = 'quarantine_reserved'
  and not exists (
      select 1
      from inv_transfer_quarantine_reservation_serial prior
      where prior.receipt_serial_id = #{serial.receiptSerialId}
         or prior.serial_id = #{serial.serialId}
  )
